    Bug 2016001 - Take2: Fix intermittent comm/mail/test/browser/composition/browser_replyFormatFlowed.js | test_reply_format_flowed - Test timed out. r=arschmitz


    Use BrowserTestUtils instead of promise_new_window.

    Differential Revision: https://phabricator.services.mozilla.com/D284459

diff --git a/mail/test/browser/composition/browser_replyFormatFlowed.js b/mail/test/browser/composition/browser_replyFormatFlowed.js
index 76de0e30b35..c7059ba9bda 100644
--- a/mail/test/browser/composition/browser_replyFormatFlowed.js
+++ b/mail/test/browser/composition/browser_replyFormatFlowed.js
@@ -38,6 +38,7 @@ add_setup(async function () {
 async function subtest_reply_format_flowed(aFlowed) {
   const file = new FileUtils.File(getTestFilePath("data/format-flowed.eml"));
   const msgc = await open_message_from_file(file);
+  await SimpleTest.promiseFocus(window);

   Services.prefs.setBoolPref("mailnews.send_plaintext_flowed", aFlowed);

diff --git a/mail/test/browser/shared-modules/FolderDisplayHelpers.sys.mjs b/mail/test/browser/shared-modules/FolderDisplayHelpers.sys.mjs
index 4cd6695b4d0..5a5678b7a5e 100644
--- a/mail/test/browser/shared-modules/FolderDisplayHelpers.sys.mjs
+++ b/mail/test/browser/shared-modules/FolderDisplayHelpers.sys.mjs
@@ -390,27 +390,33 @@ export async function open_message_from_file(file) {
     .setQuery("type=application/x-message-display")
     .finalize();

-  const newWindowPromise = promise_new_window("mail:messageWindow");
-  const win = mc.openDialog(
+  const newWindowPromise = BrowserTestUtils.domWindowOpenedAndLoaded(
+    null,
+    async win => {
+      return (
+        win.location.href == "chrome://messenger/content/messageWindow.xhtml"
+      );
+    }
+  );
+  mc.openDialog(
     "chrome://messenger/content/messageWindow.xhtml",
     "_blank",
     "all,chrome,dialog=no,status,toolbar",
     fileURL
   );
-  await BrowserTestUtils.waitForEvent(win, "load");
+  const win = await newWindowPromise;
   const aboutMessage = get_about_message(win);
   await BrowserTestUtils.waitForEvent(aboutMessage, "MsgLoaded");

-  const msgc = await newWindowPromise;
-  await wait_for_message_display_completion(msgc, true);
-  if (Services.focus.activeWindow != msgc) {
+  await wait_for_message_display_completion(win, true);
+  if (Services.focus.activeWindow != win) {
     await new Promise(resolve =>
-      msgc.addEventListener("activate", resolve, { once: true })
+      win.addEventListener("activate", resolve, { once: true })
     );
   }
   await TestUtils.waitForTick();

-  return msgc;
+  return win;
 }

